INSERT IGNORE INTO `admin_user` (`id`, `username`, `password`) VALUES
(1, 'admin', '$2b$10$HaqjLeg9kT7e9vY/3mKkjOkmR7v5P06oLD3ovljL1QaMr5oeXBmh2');
INSERT IGNORE INTO `chapter` (`id`, `title`, `content`, `interpretation`) VALUES
(1, '道可道', '道可道，非常道；名可名，非常名。无名，天地之始；有名，万物之母。故常无欲，以观其妙；常有欲，以观其徼。此两者，同出而异名，同谓之玄。玄之又玄，众妙之门。', '这是道德经的开篇，老子告诉我们：能用语言表达的道，就不是永恒的道；能用名字称呼的名，就不是永恒的名。意思是说，真正的真理和本质，往往超越了言语和定义的范围。'),
(2, '天下皆知美', '天下皆知美之为美，斯恶已；皆知善之为善，斯不善已。故有无相生，难易相成，长短相形，高下相倾，音声相和，前后相随。是以圣人处无为之事，行不言之教，万物作焉而不辞，生而不有，为而不恃，功成而弗居。夫唯弗居，是以不去。', '老子在告诉我们一个深刻的道理：事物都是相对的。当我们定义了什么是美，就自然产生了什么是丑；知道了什么是善，也就有了不善的概念。'),
(3, '不尚贤', '不尚贤，使民不争；不贵难得之货，使民不为盗；不见可欲，使民心不乱。是以圣人之治，虚其心，实其腹，弱其志，强其骨。常使民无知无欲，使夫智者不敢为也。为无为，则无不治。', '这一章讲的是社会治理的智慧。老子认为，不过度推崇贤能，人们就不会争斗；不把稀有物品看得太珍贵，人们就不会去偷盗。'),
(4, '道冲', '道冲，而用之或不盈。渊兮，似万物之宗。挫其锐，解其纷，和其光，同其尘。湛兮，似或存。吾不知谁之子，象帝之先。', '道是空虚的，但作用却是无穷无尽的。它深邃得像万物的根源。挫其锐、解其纷、和其光、同其尘，这是内敛包容的智慧。'),
(5, '天地不仁', '天地不仁，以万物为刍狗；圣人不仁，以百姓为刍狗。天地之间，其犹橐龠乎？虚而不屈，动而愈出。多言数穷，不如守中。', '天地是公平的，不会偏袒任何一方，对万物一视同仁。这里的"不仁"不是不仁慈，而是超越了好恶情感的公平。'),
(6, '谷神不死', '谷神不死，是谓玄牝。玄牝之门，是谓天地根。绵绵若存，用之不勤。', '谷神象征着虚空而生生不息的力量，它是神秘的母性力量。老子用"玄牝"来形容这种创造力。'),
(7, '天长地久', '天长地久。天地所以能长且久者，以其不自生，故能长生。是以圣人后其身而身先，外其身而身存。非以其无私邪？故能成其私。', '天地之所以长久，是因为它们不为自己而生，所以能够长久存在。圣人把自己放在后面，反而能领先。'),
(8, '上善若水', '上善若水。水善利万物而不争，处众人之所恶，故几于道。居善地，心善渊，与善仁，言善信，政善治，事善能，动善时。夫唯不争，故无尤。', '最高尚的品格就像水一样。水滋润万物却不与万物争斗，愿意停留在众人厌恶的低洼之地，所以最接近于道。'),
(9, '持而盈之', '持而盈之，不如其已；揣而锐之，不可长保。金玉满堂，莫之能守；富贵而骄，自遗其咎。功成身退，天之道。', '手持盈满，不如适可而止；磨得锋芒太露，难以长久保持。金玉满堂，无人能守；富贵而骄横，自招灾祸。功成名就后急流勇退，这才符合天道。'),
(10, '载营魄抱一', '载营魄抱一，能无离乎？专气致柔，能婴儿乎？涤除玄览，能无疵乎？爱民治国，能无为乎？天门开阖，能为雌乎？明白四达，能无知乎？生之畜之，生而不有，为而不恃，长而不宰，是谓玄德。', '精神和形体合一，能不分离吗？结聚精气以致柔顺，能像婴儿一样吗？洗刷心智，能没有瑕疵吗？爱民治国，能无为而治吗？'),
(11, '三十辐共一毂', '三十辐共一毂，当其无，有车之用。埏埴以为器，当其无，有器之用。凿户牖以为室，当其无，有室之用。故有之以为利，无之以为用。', '车轮的三十根辐条汇集到一个毂中，正是因为毂的中空，才有了车的作用。器皿因为中空才能盛物，门窗因为中空才能作为房间使用。老子以此说明"无"的价值：实实在在的"有"带来便利，而空无的"无"才真正发挥作用。'),
(12, '五色令人目盲', '五色令人目盲；五音令人耳聋；五味令人口爽；驰骋畋猎，令人心发狂；难得之货，令人行妨。是以圣人为腹不为目，故去彼取此。', '过多的色彩会让人眼花缭乱，过多的音乐会让人听觉迟钝，过度的美味会让人味觉麻木。老子提醒我们：声色犬马的享受会让人心神不宁，对稀有货物的追逐会让人行为失当。圣人注重内在的充实，而非外在的感官刺激。'),
(13, '宠辱若惊', '宠辱若惊，贵大患若身。何谓宠辱若惊？宠为下，得之若惊，失之若惊，是谓宠辱若惊。何谓贵大患若身？吾所以有大患者，为吾有身，及吾无身，吾有何患？故贵以身为天下，若可寄天下；爱以身为天下，若可托天下。', '受到宠爱和受到屈辱都会让人惊恐，这是因为人们太看重自身的得失。老子指出，只有那些能够放下自我、以天下为己任的人，才值得托付天下。'),
(14, '视之不见', '视之不见，名曰夷；听之不闻，名曰希；搏之不得，名曰微。此三者不可致诘，故混而为一。其上不皦，其下不昧。绳绳不可名，复归于无物。是谓无状之状，无物之象，是谓惚恍。迎之不见其首，随之不见其后。执古之道，以御今之有。能知古始，是谓道纪。', '道是无形无相的：看不见、听不到、摸不着。它既不明亮也不昏暗，绵绵不绝却难以名状，最终回归于虚无。掌握这种古老的智慧，就能驾驭当下的一切。'),
(15, '古之善为士者', '古之善为士者，微妙玄通，深不可识。夫唯不可识，故强为之容：豫兮若冬涉川；犹兮若畏四邻；俨兮其若客；涣兮若冰之将释；敦兮其若朴；旷兮其若谷；混兮其若浊。孰能浊以静之徐清？孰能安以久动之徐生？保此道者，不欲盈。夫唯不盈，故能蔽不新成。', '古代得道之士，深奥玄妙，难以捉摸。他们小心翼翼如冬天过河，谨慎警惕如防备邻国。正是因为他们不自满，所以能够去旧更新，始终保持活力。'),
(16, '致虚极', '致虚极，守静笃。万物并作，吾以观复。夫物芸芸，各复归其根。归根曰静，静曰复命。复命曰常，知常曰明。不知常，妄作凶。知常容，容乃公，公乃王，王乃天，天乃道，道乃久，没身不殆。', '达到极致的虚空，坚守真正的宁静。万物生长繁荣，我观察它们的循环往复。万物最终都会回归根本，回归根本就是宁静。认识这种规律就是明智，违背它就会招致灾祸。'),
(17, '太上', '太上，不知有之；其次，亲而誉之；其次，畏之；其次，侮之。信不足焉，有不信焉。悠兮其贵言。功成事遂，百姓皆谓我自然。', '最好的统治者，百姓根本不知道他的存在；其次的，百姓亲近并称赞他；再次的，百姓畏惧他；最差的，百姓轻蔑他。统治者的诚信不足，百姓就不信任他。功业完成，百姓都说"我们本来就是这样"。'),
(18, '大道废', '大道废，有仁义；智慧出，有大伪；六亲不和，有孝慈；国家昏乱，有忠臣。', '当大道被废弃时，才会提倡仁义；当智慧出现时，才会产生大的虚伪；当家庭不和时，才会彰显孝顺慈爱；当国家混乱时，才会显现忠臣。这些都是大道丧失后的补救。'),
(19, '绝圣弃智', '绝圣弃智，民利百倍；绝仁弃义，民复孝慈；绝巧弃利，盗贼无有。此三者以为文，不足。故令有所属：见素抱朴，少私寡欲，绝学无忧。', '抛弃圣智和机巧，百姓才能得到百倍的好处。老子主张保持朴素本色，减少私心和欲望，这样才能回归真正的安宁与和谐。'),
(20, '唯之与阿', '唯之与阿，相去几何？善之与恶，相去若何？人之所畏，不可不畏。荒兮其未央哉！众人熙熙，如享太牢，如春登台。我独泊兮其未兆，如婴儿之未孩。儽儽兮若无所归。众人皆有馀，而我独若遗。我愚人之心也哉！沌沌兮，俗人昭昭，我独昏昏；俗人察察，我独闷闷。澹兮其若海，飂兮若无止。众人皆有以，而我独顽似鄙。我独异于人，而贵食母。', '恭应与怠慢，相差多少？善恶之间，又有多远？老子感叹世人的忙碌与追逐，自己却保持愚钝朴素的状态。众人炫耀聪明，我却保持昏昧；众人都有所作为，我却顽固鄙陋。我与众不同，因为我以道为滋养。'),
(21, '孔德之容', '孔德之容，惟道是从。道之为物，惟恍惟惚。惚兮恍兮，其中有象；恍兮惚兮，其中有物。窈兮冥兮，其中有精；其精甚真，其中有信。自古及今，其名不去，以阅众甫。吾何以知众甫之状哉？以此。', '大德的样子，完全遵循道。道这个东西，恍恍惚惚，难以捉摸，但其中确实有形象、有实物、有精华。自古至今，道的名号从未消失，我正是通过它来认识万物的开端。'),
(22, '曲则全', '曲则全，枉则直，洼则盈，敝则新，少则得，多则惑。是以圣人抱一为天下式。不自见，故明；不自是，故彰；不自伐，故有功；不自矜，故长。夫唯不争，故天下莫能与之争。古之所谓曲则全者，岂虚言哉！诚全而归之。', '委曲往往能保全，低洼反能充盈，少取反而多得。正因为不争，所以天下没有人能和他争。这是古人传下的智慧，绝不是空话。'),
(23, '希言自然', '希言自然。故飘风不终朝，骤雨不终日。孰为此者？天地。天地尚不能久，而况于人乎？故从事于道者，道者同于道，德者同于德，失者同于失。同于道者，道亦乐得之；同于德者，德亦乐得之；同于失者，失亦乐得之。信不足焉，有不信焉。', '少说话才合乎自然。狂风刮不了一早晨，暴雨下不了一整天。天地都不能长久维持激烈的状态，何况人呢？与道同道就会得道，与德同德就会得德，与失同失就会失道。'),
(24, '企者不立', '企者不立；跨者不行；自见者不明；自是者不彰；自伐者无功；自矜者不长。其在道也，曰馀食赘行。物或恶之，故有道者不处。', '踮起脚尖站立不稳，跨大步前行走不远。自我表现的人不明智，自以为是的人不显赫。这些行为在道的看来，就像剩饭赘瘤一样令人厌恶。'),
(25, '有物混成', '有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天下母。吾不知其名，字之曰道，强为之名曰大。大曰逝，逝曰远，远曰反。故道大，天大，地大，王亦大。域中有四大，而王居其一焉。人法地，地法天，天法道，道法自然。', '有一个混然而成的东西，在天地诞生之前就已经存在。它寂静而空旷，独立存在而不改变，循环运行而不停止，可以成为天下的母亲。我不知道它的名字，就把它叫做"道"，勉强给它取名叫"大"。人效法地，地效法天，天效法道，道效法自然。'),
(26, '重为轻根', '重为轻根，静为躁君。是以圣人终日行不离辎重。虽有荣观，燕处超然。奈何万乘之主，而以身轻天下？轻则失本，躁则失君。', '稳重是轻率的根本，宁静是躁动的主宰。圣人整天行进都不离开载重的车辆，虽有荣华景象，却安然超脱。为什么大国的君主还要以轻率的态度对待天下呢？轻率会失去根本，躁动会失去主导权。'),
(27, '善行无辙迹', '善行无辙迹，善言无瑕谪；善数不用筹策；善闭无关楗而不可开，善结无绳约而不可解。是以圣人常善救人，故无弃人；常善救物，故无弃物。是谓袭明。故善人者，不善人之师；不善人者，善人之资。不贵其师，不爱其资，虽智大迷，是谓要妙。', '善于行走的人不留痕迹，善于说话的人没有瑕疵。圣人总是善于拯救人，所以没有被遗弃的人；总是善于拯救物，所以没有被废弃的物。这就是承袭光明的智慧。'),
(28, '知其雄', '知其雄，守其雌，为天下溪。为天下溪，常德不离，复归于婴儿。知其白，守其黑，为天下式。为天下式，常德不忒，复归于无极。知其荣，守其辱，为天下谷。为天下谷，常德乃足，复归于朴。朴散则为器，圣人用之，则为官长，故大制不割。', '深知雄强，却甘守雌柔，成为天下的溪流。深知明亮，却甘守暗昧，成为天下的法式。深知荣耀，却甘守屈辱，成为天下的川谷。朴素的本质分散后成为各种器具，圣人使用它们，成为管理者，所以完善的政治不会割裂朴素。'),
(29, '将欲取天下', '将欲取天下而为之，吾见其不得已。天下神器，不可为也，不可执也。为者败之，执者失之。故物或行或随，或歔或吹，或强或羸，或挫或隳。是以圣人去甚，去奢，去泰。', '想要治理天下却要用强力去做，我看是达不到目的的。天下是神圣的器物，不可以强行作为，不可以把持。强行作为的会失败，强行把持的会失去。所以圣人要去除极端的、奢侈的、过度的措施。'),
(30, '以道佐人主者', '以道佐人主者，不以兵强天下。其事好还。师之所处，荆棘生焉。大军之后，必有凶年。善者果而已，不敢以取强。果而勿矜，果而勿伐，果而勿骄，果而不得已，果而勿强。物壮则老，是谓不道，不道早已。', '用道辅佐君主的人，不靠兵力在天下逞强。用兵这件事必然会得到报复。军队驻扎过的地方，荆棘丛生；大战之后，必有灾荒。只要达到目的就好，不敢逞强。达到目的不骄傲，达到目的是出于不得已，达到目的不逞强。事物强壮了就会衰老，这不符合道，不符合道就会早亡。'),
(31, '夫佳兵者', '夫佳兵者，不祥之器，物或恶之，故有道者不处。君子居则贵左，用兵则贵右。兵者不祥之器，非君子之器，不得已而用之，恬淡为上。胜而不美，而美之者，是乐杀人。夫乐杀人者，则不可以得志于天下矣。吉事尚左，凶事尚右。偏将军居左，上将军居右，言以丧礼处之。杀人之众，以悲哀泣之，战胜以丧礼处之。', '兵器是不祥的东西，大家都厌恶它，所以有道的人不使用它。君子平时以左为贵，打仗时以右为贵。打仗是不祥的事，不是君子该做的事，只有在不得已时才使用。战争即使胜利了也不值得赞美，如果赞美战争就是喜欢杀人。喜欢杀人的人，不可能在天下实现自己的志向。'),
(32, '道常无名', '道常无名。朴虽小，天下莫能臣。侯王若能守之，万物将自宾。天地相合，以降甘露，民莫之令而自均。始制有名，名亦既有，夫亦将知止，知止所以不殆。譬道之在天下，犹川谷之于江海。', '道永远没有名字。它虽然幽微，天下却没有谁能支配它。侯王如果能守住它，万物都会自动归顺。天地相合降下甘露，没人命令却自然均匀。建立了制度就有了名分，名分既然有了，就要知道适可而止。道在天下，就像溪流流向江海一样自然。'),
(33, '知人者智', '知人者智，自知者明。胜人者有力，自胜者强。知足者富。强行者有志。不失其所者久。死而不亡者寿。', '了解别人是智慧，了解自己是高明。战胜别人是有力，战胜自己是强大。知足的人富有。坚持力行的人有志向。不失本分的人长久。身死而精神不朽的人才是真正的长寿。'),
(34, '大道泛兮', '大道泛兮，其可左右。万物恃之以生而不辞，功成不名有。衣养万物而不为主，常无欲，可名于小；万物归焉而不为主，可名为大。以其终不自为大，故能成其大。', '大道广泛啊，可以左右一切。万物依靠它生长而不推辞，功业成就却不占有名誉。它养育万物却不做主宰，可以说它渺小；万物归向它却不做主宰，可以说它伟大。正因为它不自以为大，所以才能成就它的伟大。'),
(35, '执大象', '执大象，天下往。往而不害，安平太。乐与饵，过客止。道之出口，淡乎其无味，视之不足见，听之不足闻，用之不足既。', '掌握了大道，天下人都会归向。归向而不互相伤害，就安宁和平。音乐和美食，只能让过客暂时停留。而道表述出来，平淡无味，看也看不见，听也听不到，但它的作用却是无穷无尽的。'),
(36, '将欲歙之', '将欲歙之，必固张之；将欲弱之，必固强之；将欲废之，必固兴之；将欲取之，必固与之。是谓微明。柔弱胜刚强。鱼不可脱于渊，国之利器不可以示人。', '想要收敛它，必先扩张它；想要削弱它，必先增强它；想要废除它，必先兴起它；想要夺取它，必先给予它。这就叫微妙的智慧。柔弱能够战胜刚强。鱼不能离开深渊，国家的利器不能随便展示给人看。'),
(37, '道常无为', '道常无为而无不为。侯王若能守之，万物将自化。化而欲作，吾将镇之以无名之朴。无名之朴，夫亦将无欲。不欲以静，天下将自定。', '道永远是无为的，却又无所不为。侯王如果能守住它，万物都会自然化育。化育中如果产生欲望，我就用无名的质朴来镇压它。无名的质朴也就是没有欲望，没有欲望就能宁静，天下自然就安定下来了。'),
(38, '上德不德', '上德不德，是以有德；下德不失德，是以无德。上德无为而无以为；下德为之而有以为。上仁为之而无以为；上义为之而有以为。上礼为之而莫之应，则攘臂而扔之。故失道而后德，失德而后仁，失仁而后义，失义而后礼。夫礼者，忠信之薄，而乱之首。前识者，道之华，而愚之始。是以大丈夫处其厚，不居其薄；处其实，不居其华。故去彼取此。', '上德不自以为有德，所以才有德；下德生怕失德，所以没有德。上德无为而无心于作为，下德有为而有心于作为。上仁有所作为却无心于作为，上义有所作为且有心于作为，上礼有所作为却得不到回应，于是就扬着胳膊强迫别人。失去了道之后才有德，失去德之后才有仁，失去仁之后才有义，失去义之后才有礼。礼是忠信薄弱的表现，是祸乱的开端。'),
(39, '昔之得一者', '昔之得一者：天得一以清；地得一以宁；神得一以灵；谷得一以盈；万物得一以生；侯王得一以为天下正。其致之，天无以清，将恐裂；地无以宁，将恐发；神无以灵，将恐歇；谷无以盈，将恐竭；万物无以生，将恐灭；侯王无以贵高将恐蹶。故贵以贱为本，高以下为基。是以侯王自谓孤、寡、不谷。此非以贱为本耶？非乎？故致数舆无舆。不欲琭琭如玉，珞珞如石。', '自古以来得到"一"的：天得到一而清明，地得到一而安宁，神得到一而灵验，山谷得到一而充盈，万物得到一而生长，侯王得到一而成为天下的首领。如果背离了这个规律，天无法清明就会破裂，地无法安宁就会震怒，神无法灵验就会消失，山谷无法充盈就会枯竭，万物无法生长就会灭亡，侯王无法保持高贵就会跌倒。所以高贵以低贱为基础，高高在上以低下为根基。'),
(40, '反者道之动', '反者道之动；弱者道之用。天下万物生于有，有生于无。', '道的运动是循环往复的，道的作用是柔弱的。天下万物产生于"有"，"有"产生于"无"。这就是道生生不息的奥秘。'),
(41, '上士闻道', '上士闻道，勤而行之；中士闻道，若存若亡；下士闻道，大笑之。不笑不足以为道。故建言有之：明道若昧；进道若退；夷道若纇；上德若谷；大白若辱；广德若不足；建德若偷；质真若渝；大方无隅；大器晚成；大音希声；大象无形；道隐无名。夫唯道，善贷且成。', '上士听了道，努力去实行；中士听了道，半信半疑；下士听了道，哈哈大笑。如果不被嘲笑，就不足以成为道。光明的道好像暗昧，前进的道好像后退，平坦的道好像崎岖。高尚的德好像低谷，最洁白的好像污垢，广大的德好像不足。最大的方形没有棱角，最大的器皿最后完成，最大的声音听不到，最大的形象没有形状。道隐藏无名，却善于帮助万物完成。'),
(42, '道生一', '道生一，一生二，二生三，三生万物。万物负阴而抱阳，冲气以为和。人之所恶，唯孤、寡、不谷，而王公以为称。故物或损之而益，或益之而损。人之所教，我亦教之。强梁者不得其死，吾将以为教父。', '道产生一，一产生二，二产生三，三产生万物。万物背负着阴而拥抱着阳，阴阳二气相交而形成和谐。人们所厌恶的就是"孤"、"寡"、"不谷"，但王公却用这些来称呼自己。所以事物有时减损它反而增益，有时增益它反而减损。强横的人不得好死，我把这作为教导的根本。'),
(43, '天下之至柔', '天下之至柔，驰骋天下之至坚。无有入无间，吾是以知无为之有益。不言之教，无为之益，天下希及之。', '天下最柔弱的东西，能够驾驭天下最坚硬的东西。无形的力量能够穿透没有间隙的东西，我因此知道了无为的好处。不言的教导，无为的好处，天下很少有人能够做到。'),
(44, '名与身孰亲', '名与身孰亲？身与货孰多？得与亡孰病？是故甚爱必大费；多藏必厚亡。知足不辱，知止不殆，可以长久。', '名声与生命哪个更亲近？生命与财物哪个更贵重？得到与失去哪个更有害？过分的吝惜必定招致巨大的破费，过多的贮藏必定招致惨重的损失。知道满足就不会受辱，知道适可而止就不会有危险，这样才能长久。'),
(45, '大成若缺', '大成若缺，其用不弊。大盈若冲，其用不穷。大直若屈，大巧若拙，大辩若讷。躁胜寒，静胜热。清静为天下正。', '最圆满的好像残缺，但它的作用不会衰竭；最充盈的好像空虚，但它的作用无穷无尽。最直的好像弯曲，最灵巧的好像笨拙，最善辩的好像口吃。清静无为才能成为天下的典范。'),
(46, '天下有道', '天下有道，却走马以粪。天下无道，戎马生于郊。祸莫大于不知足；咎莫大于欲得。故知足之足，常足矣。', '天下有道时，战马被退回去用于耕田；天下无道时，怀孕的母马都要上战场。最大的祸害是不知足，最大的过错是贪得无厌。所以知道满足的这种满足，才是永恒的满足。'),
(47, '不出户', '不出户，知天下；不窥牖，见天道。其出弥远，其知弥少。是以圣人不行而知，不见而名，不为而成。', '不用出门就能了解天下，不用望窗外就能认识天道。走得越远，知道的反而越少。所以圣人不用出行就能了解，不用观察就能命名，不用作为就能成就。'),
(48, '为学日益', '为学日益，为道日损。损之又损，以至于无为。无为而无不为。取天下常以无事，及其有事，不足以取天下。', '学习要每天增加，修道要每天减少。减少再减少，直到达到无为的境界。无为却能无所不为。治理天下经常要用无为的方式，如果有为，就不足以治理天下了。'),
(49, '圣人无常心', '圣人无常心，以百姓心为心。善者，吾善之；不善者，吾亦善之，德善。信者，吾信之；不信者，吾亦信之，德信。圣人在天下，歙歙为天下浑其心，百姓皆注其耳目，圣人皆孩之。', '圣人没有固定的心意，以百姓的心意作为自己的心意。善良的人，我善待他；不善良的人，我也善待他，这样就得到了善。守信的人，我信任他；不守信的人，我也信任他，这样就得到了信。圣人在天下，收敛自己的欲望，使天下人的心意浑淳，百姓都专注于视听，圣人使他们都像婴儿一样纯真。'),
(50, '出生入死', '出生入死。生之徒，十有三；死之徒，十有三；人之生，动之死地，亦十有三。夫何故？以其生生之厚。盖闻善摄生者，陆行不遇兕虎，入军不被甲兵；兕无所投其角，虎无所措其爪，兵无所容其刃。夫何故？以其无死地。', '人出世为生，入地为死。长寿的人占十分之三，短命的人占十分之三，本来可以长寿却因过度追求享养而早死的人也占十分之三。为什么会这样呢？因为他们过度地追求生存。听说善于养生的人，在路上不会遇到犀牛和老虎，在战场上不会被兵器伤害。犀牛无处用它的角，老虎无处用它的爪，兵器无处用它的刃。为什么呢？因为他没有进入死亡的境地。'),
(51, '道生之', '道生之，德畜之，物形之，势成之。是以万物莫不尊道而贵德。道之尊，德之贵，夫莫之命常自然。故道生之，德畜之；长之育之；亭之毒之；养之覆之。生而不有，为而不恃，长而不宰，是谓玄德。', '道产生万物，德养育万物，物质使万物成形，环境使万物成长。所以万物没有不尊崇道、不重视德的。道被尊崇，德被重视，没有人命令它们，而它们总是自然而然。所以道产生万物，德养育万物，使万物成长发育，使万物结果成熟，对万物爱护保护。产生万物却不占有，养育万物却不自恃，统领万物却不主宰，这就是深远的德。'),
(52, '天下有始', '天下有始，以为天下母。既得其母，以知其子；既知其子，复守其母，没身不殆。塞其兑，闭其门，终身不勤。开其兑，济其事，终身不救。见小曰明，守柔曰强。用其光，复归其明，无遗身殃；是为习常。', '天下有个开端，可以作为天下的母亲。既然找到了母亲，就能认识儿子；既然认识了儿子，又坚守着母亲，终生都不会有危险。堵塞欲望的孔窍，关闭欲望的门径，终生都不会劳累。打开欲望的孔窍，完成世俗的事情，终生都不可救药。能看到细微叫作明，能坚守柔弱叫作强。运用智慧的光芒，回归到明智，不给自己留下祸殃，这就是遵循常道。'),
(53, '使我介然有知', '使我介然有知，行于大道，唯施是畏。大道甚夷，而人好径。朝甚除，田甚芜，仓甚虚；服文彩，带利剑，厌饮食，财货有馀；是谓盗夸。非道也哉！', '假如我稍微有点知识，我就在大道上行走，唯恐走入邪路。大道很平坦，但人们却喜欢走小路。朝廷很整洁，农田却很荒芜，粮仓却很空虚。穿着华丽的衣服，佩戴锋利的宝剑，吃厌了美味佳肴，占有多余的财货，这叫做强盗头子，这绝不是道！'),
(54, '善建者不拔', '善建者不拔，善抱者不脱，子孙以祭祀不辍。修之于身，其德乃真；修之于家，其德乃馀；修之于乡，其德乃长；修之于国，其德乃丰；修之于天下，其德乃普。故以身观身，以家观家，以乡观乡，以国观国，以天下观天下。吾何以知天下然哉？以此。', '善于建立的不可拔除，善于抱持的不会脱落，子孙因此能够世代祭祀不断。把这个道理应用于自身，德就真实；应用于家庭，德就有余；应用于乡里，德就长久；应用于国家，德就丰富；应用于天下，德就普及。所以用自身的道理观察自身，用家庭的道理观察家庭，用乡里的道理观察乡里，用国家的道理观察国家，用天下的道理观察天下。我凭什么知道天下是这样的呢？就是用这种方法。'),
(55, '含德之厚', '含德之厚，比于赤子。蜂蠆虺蛇不螫，猛兽不据，攫鸟不搏。骨弱筋柔而握固。未知牝牡之合而全作，精之至也。终日号而不嗄，和之至也。知和曰常，知常曰明，益生曰祥。心使气曰强。物壮则老，谓之不道，不道早已。', '含德深厚的人，就像初生的婴儿。毒虫不咬他，猛兽不伤害他，凶鸟不搏击他。他的筋骨柔弱，拳头却握得很紧。不懂男女交合却生殖器勃起，这是精气充足的缘故。整天哭叫却嗓子不哑，这是元气和谐的缘故。懂得和谐叫作常，懂得常叫作明，贪求生活享受叫作祥，欲望任气使气叫作强。事物壮大了就会衰老，这叫作不合乎道，不合乎道就会早亡。'),
(56, '知者不言', '知者不言，言者不知。塞其兑，闭其门，挫其锐，解其分，和其光，同其尘，是谓玄同。故不可得而亲，不可得而疏；不可得而利，不可得而害；不可得而贵，不可得而贱。故为天下贵。', '有智慧的人不说话，说话的人没有智慧。堵塞欲望的孔窍，关闭欲望的门径，磨掉锋芒，化解纠纷，调和光辉，混同尘世，这就是深奥的同一。所以对它不能亲近，也不能疏远；不能使它得利，也不能使它受害；不能使它尊贵，也不能使它卑贱。所以它被天下人所重视。'),
(57, '以正治国', '以正治国，以奇用兵，以无事取天下。吾何以知其然哉？以此：天下多忌讳，而民弥贫；民多利器，国家滋昏；人多伎巧，奇物滋起；法令滋彰，盗贼多有。故圣人云：我无为，而民自化；我好静，而民自正；我无事，而民自富；我无欲，而民自朴。', '用清正来治理国家，用奇谋来用兵，用无为来夺取天下。我怎么知道是这样的呢？根据这些现象：天下的禁忌越多，百姓越贫穷；民间的利器越多，国家越混乱；人们的技巧越多，邪怪的事物越兴起；法令越森严，盗贼越多。所以圣人说：我无为，百姓自然感化；我好静，百姓自然端正；我无事，百姓自然富足；我无欲，百姓自然纯朴。'),
(58, '其政闷闷', '其政闷闷，其民淳淳；其政察察，其民缺缺。祸兮，福之所倚；福兮，祸之所伏。孰知其极？其无正也。正复为奇，善复为妖。人之迷，其日固久。是以圣人方而不割，廉而不刿，直而不肆，光而不耀。', '政治宽厚，百姓就淳朴；政治严苛，百姓就狡诈。灾祸是幸福倚存的地方，幸福是灾祸潜伏的地方。谁知道它们的终极结果？它们并没有确定的标准。正常可能变为奇怪，善良可能变为邪恶。人们的迷惑，时间已经很长了。所以圣人方正而不割伤人，锐利而不刺伤人，直率而不放肆，光亮而不刺眼。'),
(59, '治人事天', '治人事天，莫若啬。夫唯啬，是谓早服；早服谓之重积德；重积德则无不克；无不克则莫知其极；莫知其极，可以有国；有国之母，可以长久；是谓深根固柢，长生久视之道。', '治理人事、侍奉天道，没有比节俭更好的了。只有节俭，才能算是早作准备；早作准备就是不断地积累德；不断地积累德就能无往而不胜；无往而不胜就无法知道他的极限；无法知道他的极限，就可以治理国家；掌握了治国的根本，就可以长久保持；这就是根深蒂固、长久生存的道理。'),
(60, '治大国', '治大国，若烹小鲜。以道莅天下，其鬼不神；非其鬼不神，其神不伤人；非其神不伤人，圣人亦不伤人。夫两不相伤，故德交归焉。', '治理大国，就像煎小鱼一样——不能经常翻动。用道来治理天下，鬼怪就不灵验；不是鬼怪不灵验，而是它的灵验不伤害人；不是它的灵验不伤害人，而是圣人也不伤害人。鬼怪和圣人都不伤害人，所以德就会回归于百姓。'),
(61, '大国者下流', '大国者下流，天下之交，天下之牝。牝常以静胜牡，以静为下。故大国以下小国，则取小国；小国以下大国，则取大国。故或下以取，或下而取。大国不过欲兼畜人，小国不过欲入事人。夫两者各得其所欲，大者宜为下。', '大国要像江河的下流一样，处于天下交汇的地方，成为天下的雌性。雌性常常以静定战胜雄性，因为静定处于下方。所以大国用谦下的态度对待小国，就能取得小国的拥护；小国用谦下的态度对待大国，就能取得大国的接纳。所以有的用谦下来取得，有的因谦下而被取得。大国不过是想聚养人，小国不过是想侍奉人。两者都能得到他们想要的，但大国更应该谦下。'),
(62, '道者万物之奥', '道者万物之奥。善人之宝，不善人之所保。美言可以市，尊行可以加人。人之不善，何弃之有？故立天子，置三公，虽有拱璧以先驷马，不如坐进此道。古之所以贵此道者何？不曰：以求得，有罪以免耶？故为天下贵。', '道是万物的奥秘所在。善人的珍宝，不善人的保护。美好的言辞可以博取尊重，高尚的行为可以见重于人。对于不善的人，为什么要抛弃呢？所以设立天子，设置三公，虽然有进献璧玉和骏马的礼仪，还不如进献这个道。古人为什么重视这个道呢？不就是说：有求的就能得到，有罪的可以免除吗？所以被天下人所重视。'),
(63, '为无为', '为无为，事无事，味无味。大小多少，报怨以德。图难于其易，为大于其细；天下难事，必作于易；天下大事，必作于细。是以圣人终不为大，故能成其大。夫轻诺必寡信，多易必多难。是以圣人犹难之，故终无难矣。', '以无为的态度去作为，以不生事的态度去做事，以无味的态度去品味。无论大小多少，都用德来报答怨恨。谋划困难的事情要从容易的地方入手，做大事要从细微的地方入手。天下的难事一定从容易的地方做起，天下的大事一定从细微的地方做起。所以圣人始终不自以为大，所以能成就他的伟大。轻易许诺的必然信用不足，把事情看得太容易的必然困难很多。所以圣人看重困难，所以终究没有困难。'),
(64, '其安易持', '其安易持，其未兆易谋。其脆易泮，其微易散。为之于未有，治之于未乱。合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。为者败之，执者失之。是以圣人无为故无败；无执故无失。民之从事，常于几成而败之。慎终如始，则无败事，是以圣人欲不欲，不贵难得之货；学不学，复众人之所过，以辅万物之自然，而不敢为。', '安定的时候容易保持，还没出现征兆的时候容易谋划。脆弱的时候容易分解，细微的时候容易消散。要在事情还没有发生时就处理，要在混乱还没有产生时就治理。合抱的大树，从毫末般的小苗长成；九层的高台，从一筐筐泥土筑起；千里的行程，从脚下一步步走出。强行作为的会失败，强行把持的会失去。所以圣人无为所以不失败，不把持所以不失去。人们做事，常常在快要成功时失败。如果在结束时还像开始时那样谨慎，就不会有失败的事。所以圣人追求别人不追求的，不看重难得的货物；学习别人不学习的，补救众人的过失，辅助万物的自然发展，而不敢强行作为。'),
(65, '古之善为道者', '古之善为道者，非以明民，将以愚之。民之难治，以其智多。故以智治国，国之贼；不以智治国，国之福。知此两者亦稽式。常知稽式，是谓玄德。玄德深矣，远矣，与物反矣，然後乃至大顺。', '古代善于用道的人，不是教导人民精明，而是使人民愚朴。人民之所以难以治理，是因为他们智巧太多。所以用智巧来治理国家，是国家的灾祸；不用智巧来治理国家，是国家的福气。懂得这两者就是法则。经常遵守这个法则，就是玄德。玄德深啊远啊，与万物回归到本原，然后达到极大的和谐。'),
(66, '江海所以能为百谷王者', '江海所以能为百谷王者，以其善下之，故能为百谷王。是以圣人欲上民，必以言下之；欲先民，必以身後之。是以圣人处上而民不重，处前而民不害。是以天下乐推而不厌。以其不争，故天下莫能与之争。', '江海所以能成为百谷的首领，是因为它善于处在下方，所以能成为百谷的首领。所以圣人要想在人民之上，必须用言词对人民表示谦下；要想在人民之前，必须把自己放在人民之后。所以圣人居于上位而人民不感到沉重，居于前列而人民不感到受害。所以天下人都乐意推戴而不厌弃。因为他不争，所以天下没有人能和他争。'),
(67, '天下皆谓我道大', '天下皆谓我道大，似不肖。夫唯大，故似不肖。若肖，久矣其细也夫！我有三宝，持而保之。一曰慈，二曰俭，三曰不敢为天下先。夫慈故能勇；俭故能广；不敢为天下先，故能成器长。今舍慈且勇；舍俭且广；舍後且先；死矣！夫慈以战则胜，以守则固。天将救之，以慈卫之。', '天下人都说我讲的道大，好像不像任何具体的事物。正因为大，所以才不像任何具体的事物。如果像的话，早就渺小了！我有三件宝物，我持守并保全它们：第一是慈爱，第二是俭朴，第三是不敢居于天下人的前面。因为有慈爱所以能勇武，因为俭朴所以能宽广，因为不敢居于天下人的前面所以能成为万物的首领。现在舍弃慈爱而追求勇武，舍弃俭朴而追求宽广，舍弃退让而追求争先，就是死路一条！慈爱用于作战就能胜利，用于防守就能巩固。上天要救助谁，就用慈爱来保护谁。'),
(68, '善为士者', '善为士者，不武；善战者，不怒；善胜敌者，不与；善用人者，为之下。是谓不争之德，是谓用人之力，是谓配天，古之极。', '善于做将帅的人不逞武勇，善于作战的人不愤怒，善于战胜敌人的人不争斗，善于用人的人对人谦下。这就叫作不争的品德，这就叫作利用别人的力量，这就叫作符合天道，这是自古以来的最高准则。'),
(69, '用兵有言', '用兵有言：吾不敢为主，而为客；不敢进寸，而退尺。是谓行无行；攘无臂；扔无敌；执无兵。祸莫大于轻敌，轻敌几丧吾宝。故抗兵相加，哀者胜矣。', '用兵的人曾说：我不敢做进攻的一方，而要做防守的一方；不敢前进一寸，而要后退一尺。这就是说：要有阵势却像没有阵势，要举起手臂却像没有举起，要对抗敌人却像没有敌人，要手持兵器却像没有兵器。最大的灾祸莫过于轻敌，轻敌几乎丧失了我的三宝。所以两军对垒，悲愤的一方会获胜。'),
(70, '吾言甚易知', '吾言甚易知，甚易行。天下莫能知，莫能行。言有宗，事有君。夫唯无知，是以不我知。知我者希，则我者贵。是以圣人被褐而怀玉。', '我的话很容易理解，很容易实行。天下却没有人能理解，没有人能实行。说话有宗旨，做事有根据。正因为人们不理解，所以不了解我。了解我的人越少，我的价值就越珍贵。所以圣人穿着粗布衣服，怀里却藏着美玉。'),
(71, '知不知', '知不知，上；不知知，病。夫唯病病，是以不病。圣人不病，以其病病，是以不病。', '知道自己有所不知道，这是上等；不知道却自以为知道，这是毛病。正因为把毛病当作毛病，所以没有毛病。圣人没有毛病，因为他把毛病当作毛病，所以没有毛病。'),
(72, '民不畏威', '民不畏威，则大威至。无狎其所居，无厌其所生。夫唯不厌，是以不厌。是以圣人自知不自见；自爱不自贵。故去彼取此。', '当人民不再畏惧权威时，大的威胁就会到来。不要逼得人民无处安居，不要压榨人民谋生的手段。只有不压榨人民，才不会被人民厌恶。所以圣人有自知之明而不自我表现，爱护自己却不自视高贵。所以要舍弃后者而保持前者。'),
(73, '勇于敢则杀', '勇于敢则杀，勇于不敢则活。此两者，或利或害。天之所恶，孰知其故？是以圣人犹难之。天之道，不争而善胜，不言而善应，不召而自来，繟然而善谋。天网恢恢，疏而不失。', '勇于敢作敢为就会遭杀身，勇于不敢作为就能存活。这两种勇，有的得利，有的受害。上天所厌恶的，谁知道其中的缘故？所以圣人对此也感到为难。天道是：不争斗而善于取胜，不说话而善于回应，不召唤而自动到来，宽缓而善于谋划。天网广大无边，稀疏却从不漏失任何事物。'),
(74, '民不畏死', '民不畏死，奈何以死惧之？若使民常畏死，而为奇者，吾得执而杀之，孰敢？常有司杀者杀。夫司杀者，是大匠斲；夫代大匠斲者，希有不伤其手矣。', '人民不畏惧死亡，为什么用死亡来恐吓他们？如果让人民真的畏惧死亡，对于那些作恶的人，我抓来杀掉，谁还敢作恶？本来有专管杀戮的天道来执行杀戮。代替天道去杀戮，就像代替木匠去砍削一样，很少有不砍伤自己手的。'),
(75, '民之饥', '民之饥，以其上食税之多，是以饥。民之难治，以其上之有为，是以难治。民之轻死，以其求生之厚，是以轻死。夫唯无以生为者，是贤于贵生。', '人民所以饥饿，是因为统治者吞食的税赋太多，所以饥饿。人民所以难治，是因为统治者妄作为，所以难治。人民所以看轻死亡，是因为统治者追求奉养太过分，所以看轻死亡。只有那些不以追求生存为目的的人，比过分看重生命的人高明。'),
(76, '人之生也柔弱', '人之生也柔弱，其死也坚强。万物草木之生也柔脆，其死也枯槁。故坚强者死之徒，柔弱者生之徒。是以兵强则灭，木强则折。强大处下，柔弱处上。', '人活着时身体是柔弱的，死后就僵硬了。万物草木活着时是柔脆的，死后就枯槁了。所以坚强属于死亡的一类，柔弱属于生存的一类。因此兵力强大就会被消灭，树木强大就会被折断。强大的处于下方，柔弱的处于上方。'),
(77, '天之道', '天之道，其犹张弓与？高者抑之，下者举之；有馀者损之，不足者补之。天之道，损有馀而补不足。人之道，则不然，损不足以奉有馀。孰能有馀以奉天下，唯有道者。是以圣人为而不恃，功成而不处，其不欲见贤。', '天道不就像张弓射箭吗？高了就压低些，低了就抬高些；有馀的就减少些，不足的就补充些。天道是减少有馀的来补充不足的。人道却不是这样，是减少不足的来供奉有馀的。谁能够把有馀的拿来供奉给天下人呢？只有得道的人。所以圣人有所作为却不自恃，功业成就却不居功，不愿意表现自己的贤能。'),
(78, '天下莫柔弱于水', '天下莫柔弱于水，而攻坚强者莫之能胜，其无以易之。弱之胜强，柔之胜刚，天下莫不知，莫能行。是以圣人云：受国之垢，是谓社稷主；受国不祥，是谓天下王。正言若反。', '天下没有比水更柔弱的，但攻坚克强却没有什么能胜过它，因为没有什么能改变它。弱能胜强，柔能胜刚，天下没有人不懂，却没有人能实行。所以圣人说：能承担国家的屈辱，才配做国家的君主；能承担国家的灾祸，才配做天下的君王。正直的话好像反话一样。'),
(79, '和大怨', '和大怨，必有馀怨，安可以为善？是以圣人执左契，而不责于人。有德司契，无德司彻。天道无亲，常与善人。', '和解深重的怨恨，必然会有残留的怨恨，这怎么能算善呢？所以圣人拿着契约的存根，而不向人讨债。有德的人就像掌管契约的人，无德的人就像掌管税收的人。天道没有偏爱，永远帮助善良的人。'),
(80, '小国寡民', '小国寡民。使有什伯之器而不用；使民重死而不远徙。虽有舟舆，无所乘之；虽有甲兵，无所陈之。使民复结绳而用之，甘其食，美其服，安其居，乐其俗。邻国相望，鸡犬之声相闻，民至老死，不相往来。', '理想的国家应该是小而人口少。即使有各种器具也不使用；让人民重视死亡而不向远方迁移。虽然有船只车辆，却没有乘坐的必要；虽然有武器装备，却没有陈列的机会。让人民回到结绳记事的状态，吃得香甜，穿得漂亮，住得安适，对习俗感到快乐。邻国之间互相看得见，鸡鸣狗叫的声音互相听得见，但人民直到老死也不互相往来。'),
(81, '信言不美', '信言不美，美言不信。善者不辩，辩者不善。知者不博，博者不知。圣人不积，既以为人己愈有，既以与人己愈多。天之道，利而不害；圣人之道，为而不争。', '真实的话不漂亮，漂亮的话不真实。善良的人不巧辩，巧辩的人不善良。有智慧的人不博学，博学的人没有智慧。圣人不积攒财物，他越是帮助别人，自己就越富有；他越是给予别人，自己就越充足。天道是利益万物而不伤害万物，圣人的法则是有所作为而不与人争斗。');
